{
  "findings": [
    {
      "check_id": "CKV_AZURE_1",
      "title": "HTTPS traffic not enforced",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "HIGH",
      "explanation": "The storage account does not enforce HTTPS traffic, which could allow data to be transmitted insecurely over HTTP."
    },
    {
      "check_id": "CKV_AZURE_8",
      "title": "Storage account replication type is not geo-redundant",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account uses locally redundant storage (LRS), which does not provide geo-redundancy. This could lead to data loss in the event of a regional failure."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"notification_storage\" {\n  name                     = \"smartgridscada${random_string.suffix.result}\"\n  resource_group_name      = azurerm_resource_group.smart_grid_rg.name\n  location                 = azurerm_resource_group.smart_grid_rg.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"GRS\"\n  enable_https_traffic_only = true\n}",
  "fix_summary": "Enforced HTTPS traffic by setting 'enable_https_traffic_only' to true and improved data redundancy by changing 'account_replication_type' to 'GRS'."
}
